import{_ as d}from"./chunks/keyword_strategy_search.p5E0eEAw.js";import{_ as h,H as s,c as g,b as l,a2 as r,K as a,d as t,e as o}from"./chunks/framework.BEqfOpL-.js";const c="/images/keyword_strategy_overview.webp",p="/images/keyword_strategy_ai_suggestions.webp",u="/images/keyword_strategy_analytics.webp",A=JSON.parse(`{"title":"Keyword Strategy","description":"Choose the search terms you want to track and decide what each keyword is for. Show targets guide your podcast's metadata; episode targets guide individual episodes. Tracking and assigning are separate: a keyword can be measured before you choose where to use it.","frontmatter":{},"headers":[],"relativePath":"features/keyword-strategy.md","filePath":"features/keyword-strategy.md"}`),w={name:"features/keyword-strategy.md"},y={id:"draft-podcasts",tabindex:"-1"};function m(k,e,f,b,v,_){const n=s("HelpWalkthrough"),i=s("Badge");return l(),g("div",null,[e[3]||(e[3]=r('<h1 id="keyword-strategy" tabindex="-1">Keyword Strategy <a class="header-anchor" href="#keyword-strategy" aria-label="Permalink to &quot;Keyword Strategy&quot;">​</a></h1><p>Choose the search terms you want to track and decide <strong>what each keyword is for</strong>. Show targets guide your podcast&#39;s metadata; episode targets guide individual episodes. Tracking and assigning are separate: a keyword can be measured before you choose where to use it.</p><p><strong>To access:</strong> <strong>Get found → Search Visibility → Strategy</strong>. The other tabs are <strong>Search Appearances · Rankings · Tracker</strong>.</p><p><a href="/images/keyword_strategy_overview.webp" title="Open screenshot at full size"><img src="'+c+'" alt="Keyword strategy with target filters, metadata coverage, and assignments"></a></p><h2 id="add-a-keyword" tabindex="-1">Add a keyword <a class="header-anchor" href="#add-a-keyword" aria-label="Permalink to &quot;Add a keyword&quot;">​</a></h2><ol><li>Type a listener&#39;s search phrase into <strong>Add a keyword</strong>.</li><li>Review related ideas when available, or track the exact phrase you entered.</li><li>If <strong>Word variations</strong> appears, review the selected variations before using <strong>Track group</strong>. Each newly tracked variation uses a keyword slot; already-tracked terms aren&#39;t added twice.</li><li>Check <strong>Used for</strong>. Adding while <strong>Show</strong> is selected assigns the term to your show; otherwise use <strong>Assign</strong> to choose its purpose.</li></ol><p><strong>Try a suggestion</strong> offers a starting point if you don&#39;t know what to search. If related search ideas are temporarily unavailable, you can still track the phrase you typed.</p><p><a href="/images/keyword_strategy_search.webp" title="Open screenshot at full size"><img src="'+d+'" alt="Add a keyword, review word variations, or track the exact phrase"></a></p><h2 id="decide-what-each-keyword-is-for" tabindex="-1">Decide what each keyword is for <a class="header-anchor" href="#decide-what-each-keyword-is-for" aria-label="Permalink to &quot;Decide what each keyword is for&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Target</th><th>When to use it</th><th>What PodSEO checks</th></tr></thead><tbody><tr><td><strong>Show</strong></td><td>A topic your whole podcast should be found for</td><td>Show title, author, and description</td></tr><tr><td><strong>Episode</strong></td><td>A topic of a planned or published episode</td><td>That episode&#39;s title and description</td></tr><tr><td><strong>Guest</strong></td><td>The name of a guest on an episode</td><td>Tracked, without scoring the name against your metadata</td></tr><tr><td><strong>Brand</strong></td><td>Your show or host name</td><td>Branded rankings, without scoring</td></tr><tr><td><strong>Competitor</strong></td><td>A phrase you want to benchmark against another show</td><td>Tracked, without scoring</td></tr><tr><td><strong>Theme</strong></td><td>A set of terms you want to organize together</td><td>Grouping, without a separate metadata score</td></tr><tr><td><strong>Unassigned</strong></td><td>A term you&#39;re still exploring</td><td>Tracked; can also contribute to show-description alignment and episode checks as described below</td></tr></tbody></table><p>A keyword can serve your show and several episodes at the same time. Adding a Brand, Guest, Competitor or Theme target does not cancel an existing Show or Episode target. Deleting the keyword removes it from tracking; removing an assignment leaves it tracked.</p><h3 id="assign-a-keyword-without-losing-its-tracking" tabindex="-1">Assign a keyword without losing its tracking <a class="header-anchor" href="#assign-a-keyword-without-losing-its-tracking" aria-label="Permalink to &quot;Assign a keyword without losing its tracking&quot;">​</a></h3><ol><li>Open <strong>Assign</strong> on a keyword row and choose <strong>The show</strong>.</li><li>Find the episode the term also describes and select it. Choices save immediately.</li><li>Close the chooser to inspect both chips.</li><li>Remove one chip with <strong>×</strong>. The other assignment and the tracked keyword stay in place.</li></ol>',13)),a(n,{src:"/walkthroughs/strategy-targets.webp",poster:"/images/keyword_strategy_overview.webp",alt:"Assign one tracked keyword to the show and an episode, then remove only its Show assignment",duration:29100,autoplay:"",loop:"",sample:""}),e[4]||(e[4]=r('<p>For guest names, choose the episode and mark the keyword as a guest. In Planner&#39;s episode panel the option is <strong>It&#39;s a guest&#39;s name</strong>.</p><h3 id="show-keywords" tabindex="-1">Show keywords <a class="header-anchor" href="#show-keywords" aria-label="Permalink to &quot;Show keywords&quot;">​</a></h3><p>Start with two or three terms that honestly describe the show. The guidance is to aim for about five, with two in the show title; this isn&#39;t a separate cap. Review the result in <strong>Content → <a href="/features/show-optimization.html">Show Optimization</a></strong>, where you work on show title, author, description, and cover.</p><h3 id="episode-keywords" tabindex="-1">Episode keywords <a class="header-anchor" href="#episode-keywords" aria-label="Permalink to &quot;Episode keywords&quot;">​</a></h3><p>Choose specific terms the episode actually covers, usually two or three. Add them here or open the episode&#39;s <strong>Keywords for this episode</strong> panel in <a href="/features/planner.html">Planner</a>. Episode keywords are available on every plan, including Free. A guest name is tracked separately from the terms used for the episode&#39;s score.</p><p>If an episode has no targets of its own, its checks use your show keywords. If no show keywords are set either, they use your Unassigned keywords. Assign episode targets when a particular episode has a more specific focus.</p><h3 id="unassigned-keywords" tabindex="-1">Unassigned keywords <a class="header-anchor" href="#unassigned-keywords" aria-label="Permalink to &quot;Unassigned keywords&quot;">​</a></h3><p>Use this as an inbox for future topics or experiments. Unassigned means no specific purpose has been chosen; it does not exclude the term from all scoring. These terms can contribute to show-description alignment and suggestions, and to episode checks when neither episode nor show keywords are set. When a term already appears in an episode, PodSEO can suggest <strong>Use for this episode</strong>. Review the proposed episode before accepting it.</p><h2 id="find-keywords-from-your-content" tabindex="-1">Find keywords from your content <a class="header-anchor" href="#find-keywords-from-your-content" aria-label="Permalink to &quot;Find keywords from your content&quot;">​</a></h2><p>Choose <strong>AI suggestions</strong> to review recommendations based on your show&#39;s content and positioning. Suggestions are grouped by purpose. Review each phrase before using <strong>Add</strong> or <strong>Add all</strong>. An episode suggestion can remain Unassigned until you choose the episode it belongs to.</p><p><a href="/images/keyword_strategy_ai_suggestions.webp" title="Open screenshot at full size"><img src="'+p+'" alt="AI keyword suggestions grouped by show and episode purpose"></a></p><p>The panel offers <strong>Generate new suggestions</strong> when your plan and current allowance permit it. Existing suggestions stay available if another generation isn&#39;t available yet.</p><h2 id="find-keywords-from-actual-listening-and-viewing" tabindex="-1">Find keywords from actual listening and viewing <a class="header-anchor" href="#find-keywords-from-actual-listening-and-viewing" aria-label="Permalink to &quot;Find keywords from actual listening and viewing&quot;">​</a></h2><p>Choose <strong>From your analytics</strong>. This view brings together real searches that produced YouTube views and the topics of episodes receiving Spotify search impressions. Read the <strong>Evidence</strong> for each phrase: a Spotify episode topic isn&#39;t an exact search query reported by Spotify.</p><p>The view compares the available audio search positions and groups terms into <strong>Open ground on audio</strong>, <strong>Checking positions</strong>, and <strong>Already found on audio</strong> where supported. Use <strong>Track</strong> to monitor a useful term, then assign it to your show or an episode.</p><p><a href="/images/keyword_strategy_analytics.webp" title="Open screenshot at full size"><img src="'+u+'" alt="From your analytics: evidence from YouTube and Spotify alongside available positions"></a></p><p>If a source is missing, the panel offers a connection link. See <a href="/features/analytics-connections.html">Analytics Connections</a>. Available detail follows your source data and plan, including YouTube&#39;s Free restrictions.</p><h2 id="check-what-s-missing-from-your-metadata" tabindex="-1">Check what&#39;s missing from your metadata <a class="header-anchor" href="#check-what-s-missing-from-your-metadata" aria-label="Permalink to &quot;Check what&#39;s missing from your metadata&quot;">​</a></h2><p>Open <strong>Strategy checks</strong> for your show-keyword coverage and episodes without their own targets. Each row also has a coverage verdict:</p><ul><li>Show keywords indicate whether the phrase appears in the title or author, description only, or is missing.</li><li>Episode keywords show how many assigned episode titles contain the term.</li><li>Brand, guest, and competitor terms are measured without being scored.</li></ul><p>Click a verdict for its breakdown. <strong>Needs attention</strong> filters show and episode keywords missing from the titles they serve. This is where the former Keyword Coverage work now lives.</p><h2 id="filter-and-organize" tabindex="-1">Filter and organize <a class="header-anchor" href="#filter-and-organize" aria-label="Permalink to &quot;Filter and organize&quot;">​</a></h2><p>Use <strong>All keywords</strong>, <strong>Show</strong>, <strong>Episodes</strong>, <strong>Brand &amp; guests</strong>, <strong>Competitors</strong>, <strong>Themes</strong>, <strong>Unassigned</strong>, <strong>Needs attention</strong>, <strong>AI suggestions</strong>, or <strong>From your analytics</strong>, as available. Episode, competitor, and theme filters can narrow further to a specific item. The <strong>Themes</strong> column and <strong>All themes</strong> filter help organize related terms.</p><p>On larger screens, select multiple rows to use the bulk assignment or removal actions. Use <strong>Help</strong> near the title for the in-app explanation of targets.</p><h2 id="read-keyword-measurements" tabindex="-1">Read keyword measurements <a class="header-anchor" href="#read-keyword-measurements" aria-label="Permalink to &quot;Read keyword measurements&quot;">​</a></h2><p><strong>Search volume</strong> indicates relative search demand. Where the six-step meter is enabled, it ranges from <strong>Very niche</strong>, <strong>Niche</strong>, <strong>Small</strong>, <strong>Medium</strong>, and <strong>Popular</strong> to <strong>Very popular</strong>; hover or focus it for its label. Other accounts may see a volume score instead. These indicators are not counts of monthly searches. A clock means the measurement isn&#39;t available yet. A niche phrase may be a better fit for your show than a crowded popular one.</p><p><strong>Difficulty</strong> describes how hard it is to compete, by platform. <strong>Popularity</strong> describes how crowded the term is; it isn&#39;t search volume. Read them together with relevance instead of chasing the largest number.</p><h2 id="keyword-allowance" tabindex="-1">Keyword allowance <a class="header-anchor" href="#keyword-allowance" aria-label="Permalink to &quot;Keyword allowance&quot;">​</a></h2><p>Your account has one tracked-keyword pool shared across all podcasts: <strong>Free 5 · Podcaster 100 · Producer 500 · Agency 50,000</strong>. Assigning a tracked keyword to several targets doesn&#39;t use another keyword slot. Adding new terms or word variations does.</p><h2 id="review-results" tabindex="-1">Review results <a class="header-anchor" href="#review-results" aria-label="Permalink to &quot;Review results&quot;">​</a></h2><p>Use <strong>Search Appearances → Show / Episodes</strong> to discover terms already ranking, <strong>Rankings → Show / Episodes</strong> to compare tracked terms across platforms, and <strong>Tracker</strong> for their history. Keep an experiment long enough to compare its results, and note the dates of live metadata changes. PodSEO doesn&#39;t change your host&#39;s metadata when you assign a keyword.</p>',31)),t("h3",y,[e[0]||(e[0]=o("Draft podcasts ",-1)),a(i,{type:"info",text:"Ready soon",class:"soon"}),e[1]||(e[1]=o()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#draft-podcasts","aria-label":'Permalink to "Draft podcasts <Badge type="info" text="Ready soon" class="soon" />"'},"​",-1))]),e[5]||(e[5]=t("p",null,[o("For a draft, Strategy is the available Search Visibility tab. Set show and episode targets before launch; live ranking results follow the published show. See "),t("a",{href:"/getting-started/pre-launch-planning.html"},"Pre-launch Planning"),o(".")],-1))])}const x=h(w,[["render",m]]);export{A as __pageData,x as default};
